-- GENERATED by `wfj generate` from data/gossip/gossip-79.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7902b41f78c36c92"] = { "Gli elfi della notte, quando lanciano incantesimi, amano stare in disparte su una gamba sola. Colpisci quella gamba, così...", "." },
  ["790444651a72455d"] = { "Le forze dei Lupi Bianchi ottengono l'⟦General's Warcry=Urlo di Guerra del Generale⟧.", "." },
  ["790d79cbec7e4f03"] = { "%s divora la carcassa!", "." },
  ["790eb106f855fc5c"] = { "Una voce chiara si leva dalla pietra...\n\nVieni da noi con un titolo, perciò ti ascolteremo, ma non mettere alla prova la nostra pazienza, {class}. Il consiglio non ha tempo per le chiacchiere oziose di qualcuno come te.", "." },
  ["7910bec8f584039a"] = { "%s perde l'orientamento", "." },
  ["791722417ace780a"] = { "E i mezzorsi Freddinverno?", "." },
  ["7918973a84e110b4"] = { "Il passato vive in queste terre desolate, {class}. Dobbiamo stare attenti a non risvegliarlo.", "." },
  ["791bdcd360fb7190"] = { "%s inizia a salmodiare uno strano incantesimo...", "." },
  ["791dd6379b723d15"] = { "Va bene...", "." },
  ["792404c316315fa5"] = { "Hai sentito? {name}, qui presente, dice che potrebbe essere stato il disertore umano Reethe a dare fuoco alla locanda!", "." },
  ["7928277620eaa1f8"] = { "Quale istruttore cerchi?", "." },
  ["7931d6d102604de2"] = { "La ricerca della ricchezza è l'unico scopo per un goblin rispettabile.\n\nBe', forse la ricchezza... e una morte bella fragorosa!", "." },
  ["793791cef604afb8"] = { "Oh, grazie, tesoro mio.", "." },
  ["793cb1203a211a9b"] = { "Chissà se i maiali hanno fame...", "." },
  ["794e23c6cd0af762"] = { "All'estremità sud-est della città c'è la ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧. Vai lì e sali al piano di sopra: troverai il chierico oscuro Beryl nella sala di lettura.", "." },
  ["795489290f316ed5"] = { "Lo spirito ti fissa intensamente negli occhi e ti afferra la mano. Senti un calore attraversarti il corpo, tanto da farti quasi cadere in ginocchio.\n\nQuando il calore svanisce, avverti dentro di te la lieve presenza di uno spirito d'orso... che rafforza la tua determinazione.", "." },
  ["795904e917dd8c46"] = { "Ce l'abbiamo fatta, <ragazzo/ragazza>! L'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ hanno finito di raccogliere tutto ciò che pensiamo ci servirà per la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. In questo momento le ultime merci vengono portate alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e arriveranno tutte entro un giorno. Dopodiché, <un/una> <eroe/eroina> <coraggioso/coraggiosa> dovrà suonare lo Scarab Gong con lo Scettro delle Sabbie Mutevoli per aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Quando quei cancelli si apriranno, la guerra avrà inizio!", "." },
  ["7965fd4fd8d6f07b"] = { "In ginocchio! Inginocchiati davanti al Brandicenere!", "." },
  ["796a5f685db25acc"] = { "Bol... Bolvar... il medaglione... usa...", "." },
  ["79732719c4ecf555"] = { "Difendete i fortilizi!", "." },
  ["79739789e33a4775"] = { "Possa Kel'Thuzad un giorno sentire la nostra vendetta.", "." },
  ["7975ff0f822eb05a"] = { "Ora, dove ho messo quel rocchetto d'argento...", "." },
  ["7982de9e5d48913e"] = { "{name} rivendica il Cimitero di Nevealta! Se nessuno interviene, l'⟦Horde=Orda⟧ lo controllerà!", "." },
  ["798ab2ffffebca76"] = { "I ⟦Agamand Mills=Mulini degli Agamand⟧ sono in mano al Flagello, {class}. Unisciti a noi!", "." },
  ["799e91d2d1d4c595"] = { "Ehilà, <signore/signorina>. Fai attenzione a dove metti i piedi da queste parti: ho perso una bomba travestita da topo e non riesco a trovarla.", "." },
  ["79a6fcdf3c4599f3"] = { "<Angela annuisce.>\n\nDopo quelle morti, i Sei decisero che la cosa migliore era sigillare il bastone dietro barriere magiche impenetrabili e nominare una sentinella: un custode del bastone... E quel compito sarebbe toccato a me.", "." },
  ["79a8b471d790490e"] = { "Ho assistito alla corruzione di Ragnaros che penetrava nei cuori e nelle menti della nazione ⟦Dark Iron=Ferroscuro⟧. Una razza un tempo onorevole, spinta alla follia... al male.\n\nQuando la costruzione dei Bastioni fu completata, la mia volontà di vivere tra la mia gente venne meno. Me ne andai da eroe della nuova nazione ⟦Dark Iron=Ferroscuro⟧. Questa tomba fu posta qui, all'ingresso della città che progettai e costruii, in onore dei miei sforzi.", "." },
  ["79b700cb9b7574e0"] = { "Cosa? Vuoi qualcosa?", "." },
  ["79b87837d71c1c9e"] = { "Ops!", "." },
  ["79c21860ab30bca2"] = { "Patetico. Voi due non meritate l'addestramento che ricevete qui, se questo è il meglio che sapete fare.", "." },
  ["79c4b4c6cdd720fd"] = { "Da molte centinaia di anni Alassin si prende cura degli animali con cui i nostri cacciatori stringono amicizia. Le sue cure sono molto ricercate dai cacciatori di queste parti. Se lo cerchi anche tu, lo troverai nell'⟦Cenarion Enclave=Enclave Cenariana⟧.", "." },
  ["79c8d5fb7b05838d"] = { "La pesca è uno sport per i vecchi che non sono morti in battaglia! Va' a cercare Lumak sul lago, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["79d5ffa9391e5cfe"] = { "È saggio che tu ti umili davanti a me, {name}, nel tuo desiderio di accrescere il tuo sapere di {class}.", "." },
  ["79da866f54df4ee1"] = { "Il contenuto delle pagine di questo tomo sembra mutare di continuo. Hai la sensazione che i tuoi pensieri vengano risucchiati dalla mente e divorati dal libro.", "." },
  ["79e7727c2d690c4c"] = { "Be', <ragazzo/ragazza>, trovi Shelby Stoneflint proprio fuori dalla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧, a Kharanos. Si prenderà cura di qualsiasi famiglio tu abbia.", "." },
  ["79ec1eb1f4361819"] = { "Addestro i cacciatori nelle vie e nelle tradizioni dei nostri antenati.", "." },
  ["79ed6806ab941a21"] = { "Qui le cose si fanno interessanti. Il mio piano è seguire la parete della montagna, tenendola alla nostra sinistra. Così non ci perderemo nella giungla e incontreremo meno ostili. Pronti?", "." },
  ["79edcaccd77f4158"] = { "18 gradi Kraklenheit. A dire il vero fa un po' freddo...", "." },
  ["79f788890ba957f4"] = { "Il maresciallo Marris aspetta da un momento all'altro la riserva da ⟦Stormwind=Roccavento⟧. . . .", "." },
  ["79f7a7f213ad9d8c"] = { "Ho osservato quattro diversi tipi di piante colpite dalla corruzione: il fiorcanto, lo sbocciavento, la sferzarapa e la night dragon. Il fiorcanto e lo sbocciavento sono piante comuni a ⟦Felwood=Vilbosco⟧, mentre la sferzarapa e la night dragon si vedono meno spesso. Sono tutte una parte vitale dell'ecosistema di ⟦Felwood=Vilbosco⟧.", "." },
})
